#include <bits/stdc++.h>

using namespace std;

using ll = long long;

vector<pair<ll, pair<ll, ll>>> answer;

void add(ll x, ll y, ll z) {
    answer.push_back({x, {y, z}});
}

void solve(ll n, ll a, ll b, ll c) {
    if ((c + a - b) % 2 != 0) return;

    ll x = (c + a - b) / 2;
    ll y = (c + b - a) / 2;
    ll z = (a + b - c) / 2;

    if (x < 1 || y < 1 || z < 1) return;

    if (x > y) swap(x, y);
    if (y > z) swap(y, z);
    if (x > y) swap(x, y);

    __int128 sum = (__int128)x + y + z;
    __int128 value = sum * sum * sum
                   - (__int128)x * x * x
                   - (__int128)y * y * y
                   - (__int128)z * z * z;

    if (value == (__int128)n * 3) {
        add(x, y, z);
    }
}

int calculate(const pair<ll, pair<ll, ll>>& a) {
    if (a.first == a.second.second) return 1;
    if (a.first == a.second.first || a.second.first == a.second.second) return 3;
    return 6;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    if (!(cin >> n)) return 0;

    if (n <= 0 || n % 3 != 0) {
        cout << 0 << '\n';
        return 0;
    }

    n /= 3;

    vector<ll> divisors;
    for (ll a = 1; a <= n / a; ++a) {
        if (n % a == 0) {
            divisors.push_back(a);
        }
    }

    for (size_t indA = 0; indA < divisors.size(); ++indA) {
        ll a = divisors[indA];
        ll d = n / a;

        for (size_t indB = indA; indB < divisors.size(); ++indB) {
            ll b = divisors[indB];
            if ((__int128)a * b * b > n) break;
            if (d % b != 0) continue;

            ll c = d / b;
            solve(n, a, b, c);
        }
    }

    sort(answer.begin(), answer.end());

    ll ans = 0;
    for (size_t i = 0; i < answer.size(); ++i) {
        if (i > 0 && answer[i] == answer[i - 1]) continue;
        ans += calculate(answer[i]);
    }

    cout << ans << '\n';
    return 0;
}

